package com.maikal.daily;
import android.content.*;
import android.appwidget.*;
import android.widget.RemoteViews;
public class MantraTheme extends android.content.BroadcastReceiver {
 public static String choice(Context c){return c.getSharedPreferences("mantra_preferences",0).getString("theme","system");}
 public static boolean dark(Context c){String v=choice(c);return "dark".equals(v)||("system".equals(v)&&(c.getResources().getConfiguration().uiMode&48)==32);}
 public static int color(Context c,int value){if(!dark(c))return value;switch(value){case 0xffffffff:case 0xfffaf8ef:case 0xfffffdf6:return 0xff182126;case 0xff253439:return 0xffe9e7df;case 0xff536159:case 0xff72756e:case 0xff66716a:return 0xffadb8b5;case 0xff25704d:case 0xff285d79:return 0xff9ccde8;case 0xff44725c:case 0xff008b47:return 0xff94c5a5;case 0xfff1f7f3:case 0xffd6d4c8:case 0xffeae8de:case 0xffe8ece4:return 0xff3f5056;default:return value;}}
 public static void activity(android.app.Activity a){a.setTheme(dark(a)?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);}
 public static void save(Context c,String value){if(!java.util.Arrays.asList("light","dark","system").contains(value))return;String old=choice(c);c.getSharedPreferences("mantra_preferences",0).edit().putString("theme",value).apply();if(!old.equals(value))refresh(c);}
 public static void refresh(Context c){AppWidgetManager manager=AppWidgetManager.getInstance(c);Class<?>[] types={TodayWidgetProvider.class,MoneySummaryWidgetProvider.class,NoteWidgetProvider.class,TrackWidgetProvider.class,TransactionWidgetProvider.class};for(Class<?> type:types){int[] ids=manager.getAppWidgetIds(new ComponentName(c,type));if(ids.length>0)c.sendBroadcast(new Intent(c,type).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE).putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS,ids));}}
 @Override public void onReceive(Context c,Intent i){if("system".equals(choice(c)))refresh(c);}
 public static void widget(Context c,RemoteViews v,int layout){if(layout==R.layout.widget_today){v.setInt(R.id.widget_today_root,"setBackgroundResource",dark(c)?R.drawable.widget_paper_dark:R.drawable.widget_paper);v.setTextColor(R.id.widget_today_theme_1,color(c,android.graphics.Color.parseColor("#253439")));v.setTextColor(R.id.widget_date,color(c,android.graphics.Color.parseColor("#66716A")));v.setTextColor(R.id.widget_empty,color(c,android.graphics.Color.parseColor("#66716A")));}if(layout==R.layout.widget_today_row){v.setTextColor(R.id.widget_row_title,color(c,android.graphics.Color.parseColor("#253439")));v.setTextColor(R.id.widget_row_detail,color(c,android.graphics.Color.parseColor("#66716A")));}if(layout==R.layout.widget_money_summary){v.setInt(R.id.widget_money_summary,"setBackgroundResource",dark(c)?R.drawable.widget_paper_dark:R.drawable.widget_paper);v.setTextColor(R.id.widget_money_summary_theme_1,color(c,android.graphics.Color.parseColor("#253439")));v.setTextColor(R.id.widget_money_period,color(c,android.graphics.Color.parseColor("#66716A")));v.setTextColor(R.id.widget_money_summary_theme_2,color(c,android.graphics.Color.parseColor("#66716A")));v.setTextColor(R.id.widget_day_expense,color(c,android.graphics.Color.parseColor("#E33D3D")));v.setTextColor(R.id.widget_money_summary_theme_3,color(c,android.graphics.Color.parseColor("#66716A")));v.setTextColor(R.id.widget_month_expense,color(c,android.graphics.Color.parseColor("#E33D3D")));v.setTextColor(R.id.widget_money_summary_theme_4,color(c,android.graphics.Color.parseColor("#66716A")));v.setTextColor(R.id.widget_month_income,color(c,android.graphics.Color.parseColor("#008B47")));v.setTextColor(R.id.widget_money_summary_theme_5,color(c,android.graphics.Color.parseColor("#66716A")));v.setTextColor(R.id.widget_month_saving,color(c,android.graphics.Color.parseColor("#285D79")));}if(layout==R.layout.widget_track){v.setInt(R.id.widget_track_card,"setBackgroundResource",dark(c)?R.drawable.widget_paper_dark:R.drawable.widget_paper);v.setTextColor(R.id.widget_track_theme_1,color(c,android.graphics.Color.parseColor("#536159")));v.setTextColor(R.id.widget_track_total,color(c,android.graphics.Color.parseColor("#285D79")));v.setTextColor(R.id.widget_track_subtitle,color(c,android.graphics.Color.parseColor("#72756E")));v.setTextColor(R.id.widget_track_apps,color(c,android.graphics.Color.parseColor("#253439")));v.setTextColor(R.id.widget_track_updated,color(c,android.graphics.Color.parseColor("#72756E")));v.setTextColor(R.id.widget_track_theme_2,color(c,android.graphics.Color.parseColor("#285D79")));}if(layout==R.layout.widget_note){v.setInt(R.id.widget_note_card,"setBackgroundResource",dark(c)?R.drawable.widget_paper_dark:R.drawable.widget_paper);v.setTextColor(R.id.widget_note_theme_1,color(c,android.graphics.Color.parseColor("#72756E")));v.setTextColor(R.id.widget_note_change,color(c,android.graphics.Color.parseColor("#285D79")));v.setTextColor(R.id.widget_note_title,color(c,android.graphics.Color.parseColor("#253439")));v.setTextColor(R.id.widget_note_body,color(c,android.graphics.Color.parseColor("#536159")));v.setTextColor(R.id.widget_note_source,color(c,android.graphics.Color.parseColor("#72756E")));}}
}
